orts d&#39;air&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_dalchimie_7&quot;&gt;Liste des sorts d&#39;alchimie&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_danimal_8&quot;&gt;Liste des sorts d&#39;animal&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_dartisanat_9&quot;&gt;Liste des sorts d&#39;artisanat&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_deau_10&quot;&gt;Liste des sorts d&#39;eau&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_d&#233;lectricit&#233;_11&quot;&gt;Liste des sorts d&#39;&#233;lectricit&#233;&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_denchantement_12&quot;&gt;Liste des sorts d&#39;enchantement&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_d&#233;vocation_13&quot;&gt;Liste des sorts d&#39;&#233;vocation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_dillusion_14&quot;&gt;Liste des sorts d&#39;illusion&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_dinvocation_15&quot;&gt;Liste des sorts d&#39;invocation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_dobscurit&#233;_16&quot;&gt;Liste des sorts d&#39;obscurit&#233;&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_bataille_17&quot;&gt;Liste des sorts de bataille&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_bien_18&quot;&gt;Liste des sorts de bien&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_chance_19&quot;&gt;Liste des sorts de chance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_chaos_20&quot;&gt;Liste des sorts de chaos&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_charme_21&quot;&gt;Liste des sorts de charme&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_climat_22&quot;&gt;Liste des sorts de climat&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_communaut&#233;_23&quot;&gt;Liste des sorts de communaut&#233;&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_connaissance_24&quot;&gt;Liste des sorts de connaissance&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_destruction_25&quot;&gt;Liste des sorts de destruction&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_discr&#233;tion_26&quot;&gt;Liste des sorts de discr&#233;tion&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_divination_27&quot;&gt;Liste des sorts de divination&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_duperie_28&quot;&gt;Liste des sorts de duperie&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_feu_29&quot;&gt;Liste des sorts de feu&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_flore_30&quot;&gt;Liste des sorts de flore&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_folie_31&quot;&gt;Liste des sorts de folie&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_force_32&quot;&gt;Liste des sorts de force&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_froid_33&quot;&gt;Liste des sorts de froid&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_gloire_34&quot;&gt;Liste des sorts de gloire&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_guerre_35&quot;&gt;Liste des sorts de guerre&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_lib&#233;ration_36&quot;&gt;Liste des sorts de lib&#233;ration&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_loi_37&quot;&gt;Liste des sorts de loi&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_magie_38&quot;&gt;Liste des sorts de magie&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_mal_39&quot;&gt;Liste des sorts de mal&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_m&#233;tal_40&quot;&gt;Liste des sorts de m&#233;tal&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_mort_41&quot;&gt;Liste des sorts de mort&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_mort-vivant_42&quot;&gt;Liste des sorts de mort-vivant&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_nature_43&quot;&gt;Liste des sorts de nature&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_n&#233;cromancie_44&quot;&gt;Liste des sorts de n&#233;cromancie&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_noblesse_45&quot;&gt;Liste des sorts de noblesse&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_protection_46&quot;&gt;Liste des sorts de protection&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_repos_47&quot;&gt;Liste des sorts de repos&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_rune_48&quot;&gt;Liste des sorts de rune&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_soins_49&quot;&gt;Liste des sorts de soins&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_soleil_50&quot;&gt;Liste des sorts de soleil&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_son_51&quot;&gt;Liste des sorts de son&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_terre_52&quot;&gt;Liste des sorts de terre&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_transmutation_53&quot;&gt;Liste des sorts de transmutation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_de_voyage_54&quot;&gt;Liste des sorts de voyage&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_draconiques_55&quot;&gt;Liste des sorts draconiques&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_&#233;l&#233;mentaires_56&quot;&gt;Liste des sorts &#233;l&#233;mentaires&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_f&#233;eriques_57&quot;&gt;Liste des sorts f&#233;eriques&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_infernaux_58&quot;&gt;Liste des sorts infernaux&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_profanes_59&quot;&gt;Liste des sorts profanes&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Liste_des_sorts_vou&#233;s_&#224;_un_grand_destin_60&quot;&gt;Liste des sorts vou&#233;s &#224; un grand destin&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;Cette &#233;tape ne concerne que les monstres utilisant la gamme de lanceur de sorts. Pour les monstres qui connaissent uniquement quelques sorts (plut&#244;t que de se concentrer principalement sur l’incantation), choisissez une gamme diff&#233;rente et attribuez au monstre l’option universelle de magie secondaire lors de l’&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;&#201;tape 7&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Le choix des sorts pour les monstres lanceurs de sorts est volontairement limit&#233; compar&#233; &#224; celui des &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; normaux puisque les monstres cr&#233;&#233;s avec le syst&#232;me de cr&#233;ation de monstres simplifi&#233; sont con&#231;us pour servir seulement le temps d’une bataille ou d’une session de jeu. Si un monstre ainsi cr&#233;&#233; appara&#238;t dans plusieurs sessions, vous pouvez changer les sorts &#224; chaque fois, tant qu’ils correspondent &#224; la nature et au th&#232;me du monstre.&lt;br /&gt;&lt;br /&gt;Les sorts que vous choisissez pour le monstre lors de cette &#233;tape repr&#233;sentent son arsenal magique total pour une rencontre. Si vous souhaitez traiter certains sorts comme des pouvoirs lanc&#233;s gr&#226;ce &#224; des parchemins, des baguettes ou des b&#226;tons, adaptez-les comme tels en cours de jeu. Quelle que soit leur source, les sorts suppl&#233;mentaires sont toujours d&#233;compt&#233;s du nombre total de sorts que le monstre peut lancer.&lt;br /&gt;&lt;br /&gt;Vous remarquerez &#233;galement que certains types de sorts n’apparaissent pas dans ces listes (notamment les sorts qui am&#233;liorent uniquement les statistiques, comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-De-Taureau.html&quot; title=&quot;Force de taureau&quot;&gt;force de taureau&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Simulacre-De-Vie.html&quot; title=&quot;Simulacre de vie&quot;&gt;simulacre de vie&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;&lt;/i&gt;) : c’est parce qu’on les lance souvent avant le combat et que le syst&#232;me de cr&#233;ation de monstres simplifi&#233; part du principe que les effets de ces sorts ont d&#233;j&#224; &#233;t&#233; int&#233;gr&#233;s aux statistiques de base du monstre.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;DD des sorts.&lt;/b&gt; Pour d&#233;terminer le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des sorts que lance le monstre, ajoutez le niveau du sort au nombre indiqu&#233; dans la colonne &#171; DD du sort &#187; de la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-1.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 1 : La gamme&quot;&gt;gamme&lt;/a&gt; du monstre. Utilisez le niveau de sort de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; ou de l’&lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;ensorceleur&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; si plusieurs classes peuvent le lancer. Si aucune de ces classes ne poss&#232;de le sort, utilisez le niveau de sort le plus haut indiqu&#233; dans la description du sort.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Choisir les sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Choisir_les_sorts_61&quot; href=&quot;#Choisir_les_sorts_61&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Le plus facile pour choisir les sorts d’un monstre consiste &#224; s&#233;lectionner une liste de sorts, parmi celles pr&#233;sent&#233;es dans les listes suivantes, correspondant au mieux au th&#232;me du monstre en vous appuyant sur les options de ce chapitre. Une cr&#233;ature f&#233;erique poss&#233;dant de puissants pouvoirs magiques pourra choisir ses sorts dans les listes des sorts d’enchantement, de f&#233;e, de nature ou de duperie. Un magicien d&#233;vou&#233; au feu pourra choisir dans la liste des sorts de feu tandis qu’un transmutateur piochera s&#251;rement dans la liste des sorts de transmutation et qu’un g&#233;n&#233;raliste consultera la liste magique ou profane.&lt;br /&gt;&lt;br /&gt;Quand vous choisissez une liste de sorts, le monstre gagne les ensembles de sorts suivants, en fonction de la tranche de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; &#224; laquelle il appartient (c’est-&#224;-dire la tranche d’incantation &#224; laquelle correspond son FP) :
&lt;ul&gt;&lt;li&gt;Les sorts principaux associ&#233;s &#224; la tranche de FP du monstre, utilisables une fois par jour. Ce sont les sorts de plus haut niveau du monstre.&lt;/li&gt;&lt;li&gt;Les sorts principaux et secondaires associ&#233;s &#224; la tranche de FP d’une cat&#233;gorie inf&#233;rieure &#224; celle du monstre, utilisables trois fois par jour. Ils correspondent aux sorts les moins puissants du monstre.&lt;/li&gt;&lt;li&gt;Les sorts principaux associ&#233;s &#224; la tranche de FP de deux cat&#233;gories inf&#233;rieure &#224; celle du monstre, utilisables &#224; volont&#233;. Ce sont les sorts de plus bas niveau du monstre.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Cette m&#233;thode permet de cr&#233;er un lanceur de sorts poss&#233;dant un petit nombre de sorts puissants qu’il peut utiliser rarement, un nombre plus important de sorts plus faibles qu’il peut utiliser souvent et des sorts tellement faibles qu’ils ont peu d’utilit&#233; en combat mais qu’il peut lancer fr&#233;quemment.&lt;br /&gt;&lt;br /&gt;Notez qu’un monstre de FP 0-3 ne gagne aucun sort &#224; volont&#233; ni aucun sort utilisable trois fois par jour tandis qu’un monstre de FP 4-7 ne gagne aucun sort &#224; volont&#233;.&lt;br /&gt;&lt;br /&gt;Inscrivez les sorts et leur nombre d’utilisations quotidiennes. Pour les exemples de monstres pr&#233;sent&#233;s plus tard dans ce chapitre, les sorts sont divis&#233;s entre les sorts d’attaque, les sorts d&#233;fensifs et les sorts utilitaires, mais cette &#233;tape est optionnelle.&lt;br /&gt;&lt;br /&gt;Quand vous choisissez une liste de sorts, le monstre gagne automatiquement l’avantage indiqu&#233; au bas de la liste. Si vous d&#233;cidez de cr&#233;er votre propre liste de sorts, choisissez l’avantage qui correspond le mieux &#224; votre monstre ou imaginez votre propre avantage pour le monstre.&lt;br /&gt;&lt;br /&gt;Par exemple, un monstre de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; 9 utilisant la liste des sorts aberrants gagne &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;bilit&#233;.html&quot; title=&quot;D&#233;bilit&#233;&quot;&gt;d&#233;bilit&#233;&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-R&#233;sistance-&#192;-La-Magie.html&quot; title=&quot;R&#233;sistance &#224; la magie&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;&lt;/i&gt; une fois par jour chacun (issus de la tranche de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de 8 &#224; 11) ; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-I.html&quot; title=&quot;Forme bestiale I&quot;&gt;forme bestiale I&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Image-Accomplie.html&quot; title=&quot;Image accomplie&quot;&gt;image accomplie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;che-Acide.html&quot; title=&quot;Fl&#232;che acide&quot;&gt;fl&#232;che acide&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l’invisibilit&#233;&lt;/a&gt;&lt;/i&gt; trois fois par jour chacun (pour la tranche de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de 4 &#224; 7) ; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frayeur.html&quot; title=&quot;Frayeur&quot;&gt;frayeur&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bras-Long.html&quot; title=&quot;Bras long&quot;&gt;bras long&lt;/a&gt;&lt;/i&gt; &#224; volont&#233; (pour la tranche de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt;] de 0 &#224; 3). Il gagne &#233;galement l’avantage de sa liste de sort, &#224; savoir le pouvoir universel de monstre de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fense-(Capacit&#233;).html&quot; title=&quot;D&#233;fense (Ext)&quot;&gt;d&#233;fense&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 16px 8px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Tranche&lt;br /&gt;de FP&lt;/td&gt;&lt;td&gt;Niveau&lt;br /&gt;de sort&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;0-3&lt;/td&gt;&lt;td&gt;0 ou 1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;4-7&lt;/td&gt;&lt;td&gt;2 ou 3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;8-11&lt;/td&gt;&lt;td&gt;4 ou 5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;12-15&lt;/td&gt;&lt;td&gt;6 ou 7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;16+&lt;/td&gt;&lt;td&gt;8 ou 9&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Choix de sorts d&#233;taill&#233;&lt;a class=&quot;headeranchor&quot; id=&quot;Choix_de_sorts_d&#233;taill&#233;_0&quot; href=&quot;#Choix_de_sorts_d&#233;taill&#233;_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces listes sont l&#224; pour vous faire gagner du temps lors du choix des sorts, mais vous pouvez aussi choisir vos sorts un &#224; un, accordez au monstre des sorts secondaires &#224; la place de sorts principaux (ce qui explique pourquoi la liste de sorts pour la tranche de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; 16+ indique &#233;galement les sorts secondaires) ou les combiner et les associer comme vous l’entendez. Pour que votre monstre reste &#233;quilibr&#233;, ne d&#233;viez pas trop du nombre de sorts indiqu&#233; pour son niveau de puissance, mais vous pouvez quand m&#234;me revoir ce nombre &#224; la hausse ou &#224; la baisse, dans les limites du raisonnable.&lt;br /&gt;&lt;br /&gt;Si vous souhaitez d&#233;terminer les sorts un &#224; un, utilisez les niveaux de sorts du tableau suivant pour chaque tranche de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Les listes de sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Les_listes_de_sorts_62&quot; href=&quot;#Les_listes_de_sorts_62&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les listes qui suivent s’appuient sur diff&#233;rentes formes d’utilisation de la magie et correspondent &#233;galement &#224; des lignages, des domaines et d’autres th&#232;mes magiques importants. Quand un monstre dispose d’une greffe de classe, utilisez la liste de sorts sugg&#233;r&#233;e pour choisir les sorts du monstre.&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
